/** One message that matched a search. */
export interface MessageHit {
  eventId: string;
  roomId: string;
  sender: string;
  body: string;
  /**
   * The body with <mark> around the matched terms. Generated by the server
   * from the stored text, so the only markup in it is the marks themselves —
   * but it is still rendered through the same sanitiser as any other message,
   * because a client should not be the place that decides what is safe.
   */
  highlighted: string;
  sentAt: string;
}

/** A conversation that matched. */
export interface RoomHit {
  id: string;
  slug?: string;
  name: string;
  topic?: string;
  visibility: "public" | "private";
  archived: boolean;
  /** Whether the searcher is already in it, so the action can be "open" or "join". */
  member: boolean;
}

/** Somebody who matched. */
export interface PersonHit {
  id: string;
  username: string;
  displayName: string;
  address: string;
}

/** One search across the whole product. */
export interface SearchResults {
  messages: MessageHit[];
  rooms: RoomHit[];
  people: PersonHit[];
}
